WITH w_agg AS ( SELECT w.w_warehouse_sk, w.w_warehouse_name, w.w_state, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_amount) AS total_return_amount FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY w.w_warehouse_sk, w.w_warehouse_name, w.w_state ), w_ranked AS ( SELECT w_agg.*, ROW_NUMBER() OVER (PARTITION BY w_state ORDER BY total_net_loss DESC) AS state_warehouse_rank, CASE WHEN total_net_loss > 100000 THEN 'Critical' WHEN total_net_loss > 50000 THEN 'Warning' ELSE 'Normal' END AS risk_level FROM w_agg ) SELECT w_warehouse_sk, w_warehouse_name, w_state, total_net_loss, total_return_amount, state_warehouse_rank, risk_level FROM w_ranked WHERE state_warehouse_rank <= 3 ORDER BY w_state, state_warehouse_rank
